// Accounts to watch. Pulls the live list from Rekindle; falls back to a static list.
const accounts = $input.first().json.data || [];
const list = accounts.length ? accounts : [
  { name: 'Finvara Pay', domain: 'finvarapay.example' },
  { name: 'Kredo Lending', domain: 'kredolending.example' },
];
// /api/accounts may omit domains; accountId is sent too so Rekindle can match either way.
return list.filter((a) => a.name).map((a) => ({ json: { accountId: a.id || null, name: a.name, domain: a.domain || null } }));

// Keep fresh headlines that mention the company and look like a buying signal.
const RULES = [
  ['FUNDING', /raises|raised|funding|series [a-e]|seed round|investment led by/i],
  ['LEADERSHIP_CHANGE', /appoints|names .* (cto|ciso|ceo|head)|joins as|new (cto|ciso|ceo)/i],
  ['HIRING_RELEVANT', /hiring|to hire|jobs|headcount/i],
  ['EXPANSION', /expands|expansion|new office|enters|launches in/i],
  ['COMPLIANCE_EVENT', /soc 2|iso 27001|rbi|cert-in|breach|audit|compliance|data protection/i],
  ['PRODUCT_LAUNCH', /launches|unveils|introduces/i],
];
const weekAgo = Date.now() - 7 * 86400000;
const out = [];
for (const [index, item] of $input.all().entries()) {
  const company = $('Companies').itemMatching(index).json;
  const title = item.json.title || '';
  const published = new Date(item.json.isoDate || item.json.pubDate || Date.now());
  if (!title.toLowerCase().includes(company.name.toLowerCase())) continue;
  if (published.getTime() < weekAgo) continue;
  const rule = RULES.find(([, re]) => re.test(title));
  if (!rule) continue;
  out.push({ json: {
    accountDomain: company.domain,
    accountId: company.accountId,
    type: rule[0],
    title: title.replace(/ - [^-]+$/, ''),
    sourceUrl: item.json.link,
    occurredAt: published.toISOString(),
    dedupeKey: `news:${company.domain || company.accountId}:${(item.json.guid || item.json.link || title).toString().slice(-120)}`,
  } });
}
return out;
